#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h> // For sleep

// Function executed by the detached thread
void* detached_thread_func(void* arg) {
    printf("Detached thread started.\n");
    sleep(1);
    printf("Detached thread finished.\n");
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread;
    int s;

    // 1. Initialize the attributes object with default values
    if ((s = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }

    // 2. Customize an attribute: Set the thread to be detached
    if ((s = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED)) != 0) {
        fprintf(stderr, "Error setting detach state: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 3. Create the thread using the custom attributes
    printf("Creating thread with detached attribute...\n");
    if ((s = pthread_create(&thread, &attr, detached_thread_func, NULL)) != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Destroy the attributes object immediately after use
    // This releases internal resources but does not affect the running thread.
    if ((s = pthread_attr_destroy(&attr)) != 0) {
        fprintf(stderr, "Error destroying attributes: %d\n", s);
        // The program should still continue, but resource cleanup failed.
    }

    printf("Main thread exiting. (The detached thread will clean itself up.)\n");
    sleep(2); // Wait for the detached thread to ensure it runs before process exit

    return 0;
}
